function validateThresholds(thresholds, validMetricIds) {
  if (!thresholds) return { valid: true };

  const errors = [];
  const thresholdEntries = Object.entries(thresholds);

  for (const [metricId, min] of thresholdEntries) {
    if (!validMetricIds.includes(metricId)) {
      errors.push(`Unknown metric id: ${metricId}`);
      continue;
    }
    if (typeof min !== 'number' || min < 0 || min > 1) {
      errors.push(`Invalid threshold for ${metricId}: minimum must be a number between 0 and 1, got ${min}`);
    }
  }

  return errors.length > 0 ? { valid: false, errors } : { valid: true };
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const validMetricIds = evaluations.map((m) => m.id);
  const thresholdValidation = validateThresholds(thresholds, validMetricIds);

  if (!thresholdValidation.valid) {
    const error = new Error('Threshold validation failed');
    error.code = 'THRESHOLD_VALIDATION_ERROR';
    error.details = thresholdValidation.errors;
    error.validMetricIds = validMetricIds;
    throw error;
  }

  const thresholdResults = [];
  let allPassed = true;

  if (thresholds) {
    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score;
      const passed = score !== null && score !== undefined && score >= min;
      if (!passed) allPassed = false;
      thresholdResults.push({
        metric: metricId,
        min,
        score,
        passed
      });
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds) {
    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

