function parseThresholds(thresholdStrs?: string[]) {
  if (!thresholdStrs || thresholdStrs.length === 0) {
    return null;
  }

  const thresholds: Record<string, number> = {};
  for (const str of thresholdStrs) {
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: ${str}. Expected format: <metric>=<number>`);
    }
    const [, metricId, minStr] = match;
    const min = Number.parseFloat(minStr);
    if (Number.isNaN(min) || min < 0 || min > 1) {
      throw new Error(`Invalid threshold value for ${metricId}: ${minStr}. Minimum must be a number between 0 and 1.`);
    }
    thresholds[metricId] = min;
  }
  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: Record<string, number> | null = null;
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    log.error((error as Error).message);
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let report: any;
  try {
    report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds
    });
  } catch (error) {
    if ((error as any)?.code === 'THRESHOLD_VALIDATION_ERROR') {
      const details = (error as any)?.details ?? [];
      const validIds = (error as any)?.validMetricIds ?? [];
      log.error('Invalid threshold metric. Valid metrics are:');
      validIds.forEach((id: string) => {
        console.error(`  - ${id}`);
