      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('supports thresholds and passes when met', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.5,
      score: expect.any(Number),
      passed: true
    });
  });

  it('fails thresholds when not met', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'world'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 }
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.5,
      score: null,
      passed: false
    });
  });

  it('rejects unknown metric in threshold', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { unknown_metric: 0.5 }
      });
    }).toThrow('Threshold validation failed');
  });

  it('rejects invalid threshold value', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { exact_match: 1.5 }
      });
    }).toThrow('Threshold validation failed');
  });

  it('includes thresholds in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9, toxicity: 0.8 }
    });
    const markdown = require('./reporters.js').toMarkdown(report);
    expect(markdown).toContain('## Thresholds');
    expect(markdown).toContain('exact_match');
    expect(markdown).toContain('toxicity');
  });

  it('does not include thresholds in report when not provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });
    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });
});

