let report: any;
try {
  report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
} catch (error) {
  if ((error as any)?.code === 'THRESHOLD_VALIDATION_ERROR') {
    const details = (error as any)?.details ?? [];
    const validIds = (error as any)?.validMetricIds ?? [];
    log.error('Invalid threshold metric. Valid metrics are:');
    validIds.forEach((id: string) => {
      console.error(`  - ${id}`);
    });
    details.forEach((detail: string) => {
      console.error(`  Error: ${detail}`);
    });
    process.exit(2);
  }
  throw error;
}

